def collect_existing_photos(apps, schema_editor):
    """
    今ある料理と食材の写真を「投稿された写真」に入れる。料理の写真2は候補として残す。
    Wikimedia の食材写真 (出典つき) は入れない。
    """

    Recipe = apps.get_model("washoku", "Recipe")
    Ingredient = apps.get_model("washoku", "Ingredient")
    MemberPhoto = apps.get_model("washoku", "MemberPhoto")

    for recipe in Recipe.objects.exclude(photo_1="", photo_2=""):

        for url in (recipe.photo_1, recipe.photo_2):
            if url:
                MemberPhoto.objects.create(recipe=recipe, url=url, user_id=recipe.submitted_by_id)

        if not recipe.photo_1:
            recipe.photo_1 = recipe.photo_2
            recipe.save(update_fields=["photo_1"])

    for ingredient in Ingredient.objects.exclude(photo_url="").filter(photo_credit=""):
        MemberPhoto.objects.create(ingredient=ingredient, url=ingredient.photo_url)


